//! Unique original appearance-proc name selection and writer judgment.
use crate::raw_fixture_policy::PatternApi as _;
use std::collections::HashSet;
use crate::{tree::SourceFile,pat,pat_match,key_policy_control::Control};
#[cfg(feature="legacy-sem")]use crate::{incr,tree::Tree};
use crate::reactive_writer_policy::{member_writer,writer_call};
#[cfg(feature="legacy-sem")]
pub fn names_in_file(f:&SourceFile)->Vec<String>{names_in_file_using(f,&mut crate::key_policy_control::Compatibility,&mut crate::key_policy_control::Compatibility).expect("original look names")}
pub fn names_in_file_using<C:Control,T:Control<Error=C::Error>>(f:&SourceFile,keep:&mut C,temp:&mut T)->Result<Vec<String>,C::Error>{names_in_file_with_program(f,keep,temp,||crate::pat!(r"\bDECLARE_APPEARANCE_PROC\s*\(\s*/[\w/]+\s*,\s*(?:TYPE_PROC_REF\(\s*[/\w]+\s*,\s*(\w+)\s*\)|PROC_REF\(\s*(\w+)\s*\))"))}
#[cfg(feature="native-policy")]
pub fn names_with_fixture<C:Control,T:Control<Error=C::Error>>(f:&SourceFile,keep:&mut C,temp:&mut T,fixture:&crate::raw_fixture_policy::Fixture<'_>)->Result<Vec<String>,C::Error>{names_in_file_with_program(f,keep,temp,||fixture.pattern(r"\bDECLARE_APPEARANCE_PROC\s*\(\s*/[\w/]+\s*,\s*(?:TYPE_PROC_REF\(\s*[/\w]+\s*,\s*(\w+)\s*\)|PROC_REF\(\s*(\w+)\s*\))",crate::raw_fixture_policy::PatternMode::Search,||crate::pat!(r"\bDECLARE_APPEARANCE_PROC\s*\(\s*/[\w/]+\s*,\s*(?:TYPE_PROC_REF\(\s*[/\w]+\s*,\s*(\w+)\s*\)|PROC_REF\(\s*(\w+)\s*\))")))}
pub fn names_in_file_with_program<P:crate::raw_fixture_policy::PatternApi,C:Control,T:Control<Error=C::Error>>(f:&SourceFile,keep:&mut C,temp:&mut T,make:impl FnOnce()->P)->Result<Vec<String>,C::Error>{keep.checkpoint()?;crate::key_policy_control::reserve(temp,||f.text().len().checked_mul(64)?.checked_add(4096))?;let row=make();let mut out=Vec::new();for line in f.clean().lines(){keep.checkpoint()?;if !line.contains("DECLARE_APPEARANCE_PROC"){continue}for m in row.captures_iter(line){keep.checkpoint()?;crate::raw_tree_report::row(keep,&mut out)?;out.push(crate::raw_tree_report::own(keep,if m.matched(1){m.s(1)}else{m.s(2)})?);}}crate::key_policy_control::reserve(keep,||out.len().checked_mul(4*std::mem::size_of::<String>())?.checked_add(128))?;out.sort();out.dedup();keep.checkpoint()?;Ok(out)}
fn add<C:Control>(set:&mut HashSet<String>,name:&str,c:&mut C)->Result<(),C::Error>{c.checkpoint()?;if set.contains(name){return Ok(())}if C::CHECKED&&set.len()==set.capacity(){let target=set.capacity().checked_mul(2).map(|n|n.max(4)).ok_or_else(||c.overflow())?;let bound=target.checked_mul(4).ok_or_else(||c.overflow())?;crate::key_policy_control::reserve(c,||bound.checked_mul(std::mem::size_of::<String>())?.checked_add(4096))?;set.try_reserve(target-set.len()).map_err(|_|c.allocation_failed())?;if set.capacity()>bound{return Err(c.allocation_failed())}}set.insert(crate::raw_tree_report::own(c,name)?);Ok(())}
pub fn merge<'a,C:Control>(rows:impl IntoIterator<Item=&'a Vec<String>>,c:&mut C)->Result<HashSet<String>,C::Error>{let mut names=HashSet::new();add(&mut names,"appearance_overlays",c)?;for row in rows{for name in row{add(&mut names,name,c)?;}}c.checkpoint()?;Ok(names)}
pub fn judge_using<C:Control,T:Control<Error=C::Error>>(file:&SourceFile,names:&HashSet<String>,keep:&mut C,temp:&mut T)->Result<Vec<(&'static str,usize)>,C::Error>{judge_with_programs(file,names,keep,temp,||crate::pat_match!(r"\s*(?:src\s*\.\s*)?(?:icon_state|icon|overlays|underlays|color|alpha|layer|plane|transform|pixel_x|pixel_y|pixel_w|pixel_z)\s*(?:=(?!=)|\+=|-=|\|=)"),&|id|match id{0=>writer_call(),1=>member_writer(),_=>unreachable!("closed look writer slot")},None)}
#[cfg(feature="native-policy")]
pub fn judge_with_fixture<C:Control,T:Control<Error=C::Error>>(file:&SourceFile,names:&HashSet<String>,keep:&mut C,temp:&mut T,fixture:&crate::raw_fixture_policy::Fixture<'_>)->Result<Vec<(&'static str,usize)>,C::Error>{judge_with_programs(file,names,keep,temp,||fixture.pattern(r"\s*(?:src\s*\.\s*)?(?:icon_state|icon|overlays|underlays|color|alpha|layer|plane|transform|pixel_x|pixel_y|pixel_w|pixel_z)\s*(?:=(?!=)|\+=|-=|\|=)",crate::raw_fixture_policy::PatternMode::Match,||crate::pat_match!(r"\s*(?:src\s*\.\s*)?(?:icon_state|icon|overlays|underlays|color|alpha|layer|plane|transform|pixel_x|pixel_y|pixel_w|pixel_z)\s*(?:=(?!=)|\+=|-=|\|=)")),&|id|crate::reactive_writer_policy::native_writer_pattern(fixture,id),Some(fixture))}
pub fn judge_with_programs<P:crate::raw_fixture_policy::PatternApi,W:Fn(usize)->P,C:Control,T:Control<Error=C::Error>>(file:&SourceFile,names:&HashSet<String>,keep:&mut C,temp:&mut T,make:impl FnOnce()->P,writers:&W,fixture:Option<&crate::raw_fixture_policy::Fixture<'_>>)->Result<Vec<(&'static str,usize)>,C::Error>{keep.checkpoint()?;crate::key_policy_control::reserve(temp,||file.text().len().checked_mul(file.rel.len().checked_mul(4)?.checked_add(512)?)?.checked_add(4096))?;let appearance_write=make();let mut out=Vec::new();let clean=file.clean();for proc in crate::dm::dx::procs_in_using(file,temp)?{keep.checkpoint()?;if !names.contains(&proc.name)||proc.path=="/atom"||proc.path=="/datum"{continue}let mut lines=Vec::new();crate::key_policy_control::reserve(temp,||proc.body_len.checked_mul(4*std::mem::size_of::<(usize,&str)>())?.checked_add(128))?;for k in 0..proc.body_len{keep.checkpoint()?;lines.push((proc.body_start+k,clean.line(proc.body_start+k)));}let found=if let Some(fixture)=fixture{crate::reactive_writer_policy::reactive_writes_lines_with_fixture(&proc,&lines,keep,temp,fixture)?}else{crate::reactive_writer_policy::reactive_writes_lines_using(&proc,&lines,keep,temp)?};for number in found{keep.checkpoint()?;let text=lines.iter().find(|(n,_)|*n==number).map(|(_,t)|*t).unwrap_or("");if suppressed_using(text,&appearance_write,writers){continue}crate::raw_tree_report::row(keep,&mut out)?;out.push(("dx_appearance_side_effect",number));}}keep.checkpoint()?;Ok(out)}
fn suppressed_using<P:crate::raw_fixture_policy::PatternApi,W:Fn(usize)->P>(text:&str,appearance_write:&P,writers:&W)->bool{appearance_write.is_match(text)&&!writers(0).is_match(text)&&!writers(1).is_match(text)}
#[cfg(feature="legacy-sem")]
pub fn scan(tree:&Tree,files:&[&SourceFile])->Vec<(&'static str,String,usize)>{let _=tree;let names=merge(&incr::facts("sys-dx-look-names",files,names_in_file),&mut crate::key_policy_control::Compatibility).expect("original look names");let mut out=Vec::new();for file in files{let rows=judge_using(file,&names,&mut crate::key_policy_control::Compatibility,&mut crate::key_policy_control::Compatibility).expect("original appearance judge");out.extend(rows.into_iter().map(|(rule,line)|(rule,file.rel.clone(),line)));}out}
